// === Tab: mySketch ===
let n_particles = 1000;
let particles = [];
let max_displacement = 5;

function setup() {
  createCanvas(800, 800);
  background(0);
  background(255);
  for (i_particle = 0; i_particle < n_particles; i_particle++) {
    particles.push(new Particle(width/2, height/2, random(3,40)));
  }
}

function draw() {

  strokeWeight(0.9);
  for (i_particle = 0; i_particle < n_particles; i_particle++) {
    particles[i_particle].move();
  }
  for (i_particle = 0; i_particle < n_particles; i_particle++) {
    particles[i_particle].show();
  }
}

class Particle {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
  }

  show() {
    circle(this.x, this.y, this.size);
  }
  move() {
    this.x+=random(-max_displacement,max_displacement);
    this.y+=random(-max_displacement,max_displacement);
  }
}

